<?php
require_once __DIR__ . '/bootstrap.php'; require_admin(); $in=json_input();
$name=trim((string)($in['customer_name']??''));$item=trim((string)($in['item_name']??''));$qty=max(1,(int)($in['qty']??1));$price=max(0,(int)($in['unit_price']??0));$discount=max(0,(int)($in['discount']??0));$source=$in['order_source']??'other';$method=$in['payment_method']??'other';$status=$in['payment_status']??'pending';
if($name===''||$item===''||!in_array($source,['phone','whatsapp','walk_in','face_to_face','other'],true)||!in_array($status,['pending','paid','failed'],true)){http_response_code(400);echo json_encode(['error'=>'Provide valid customer, item, source and payment details.']);exit;}
$subtotal=$qty*$price;$total=max(0,$subtotal-$discount);$reference='MIL-'.gmdate('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$orderStatus=$status==='paid'?'confirmed':'pending_payment';$pdo=get_db();$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO orders(reference,customer_name,customer_email,customer_phone,delivery_address,subtotal,discount,total,order_source,payment_method,payment_reference,payment_status,order_status,notes,verified_by,verified_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$reference,$name,trim((string)($in['customer_email']??'')),trim((string)($in['customer_phone']??'')),trim((string)($in['delivery_address']??'')),$subtotal,$discount,$total,$source,$method,trim((string)($in['payment_reference']??''))?:null,$status,$orderStatus,trim((string)($in['notes']??'')),$status==='paid'?current_user_id():null,$status==='paid'?date('Y-m-d H:i:s'):null]);$id=$pdo->lastInsertId();$pdo->prepare('INSERT INTO order_items(order_id,item_id,item_name,unit_price,qty,subtotal) VALUES(?,?,?,?,?,?)')->execute([$id,'manual',$item,$price,$qty,$subtotal]);$pdo->commit();echo json_encode(['success'=>true,'reference'=>$reference]);}catch(Throwable $e){$pdo->rollBack();http_response_code(500);echo json_encode(['error'=>'Could not create manual order.']);}
